class TrieNode {
  constructor() {
    this.children = new Map(); // char -> TrieNode
    this.isEnd    = false;
  }
}

class Trie {
  constructor() { this.root = new TrieNode(); }

  // O(k) — k = word length; creates missing nodes
  insert(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) {
        node.children.set(ch, new TrieNode());
      }
      node = node.children.get(ch);
    }
    node.isEnd = true;
  }

  // Shared traversal: O(k). Returns null if path breaks.
  #walk(str) {
    let node = this.root;
    for (const ch of str) {
      if (!node.children.has(ch)) return null;
      node = node.children.get(ch);
    }
    return node;
  }

  // O(k) — exact word membership
  search(word) {
    const node = this.#walk(word);
    return node !== null && node.isEnd;
  }

  // O(p) — any stored word begins with prefix?
  startsWith(prefix) {
    return this.#walk(prefix) !== null;
  }

  // O(p + output) — all words sharing the prefix
  autocomplete(prefix) {
    const node = this.#walk(prefix);
    if (!node) return [];
    const results = [];
    this.#dfs(node, prefix, results);
    return results;
  }

  #dfs(node, current, results) {
    if (node.isEnd) results.push(current);
    for (const [ch, child] of node.children) {
      this.#dfs(child, current + ch, results);
    }
  }
}

const trie = new Trie();
['cat','car','card','care','dog','door','dot'].forEach(w => trie.insert(w));

console.log(trie.search('car'));         // true
console.log(trie.search('ca'));          // false — not end-of-word
console.log(trie.startsWith('ca'));      // true — prefix exists
console.log(trie.autocomplete('ca'));    // ['cat','car','card','care']
console.log(trie.autocomplete('do'));    // ['dog','door','dot']
console.log(trie.autocomplete('xyz'));   // []

// Delete a word — post-order cleanup of orphaned nodes
function deleteWord(root, word, depth = 0) {
  if (!root) return false;

  if (depth === word.length) {
    // Reached end of word
    if (!root.isEnd) return false;  // word was never in trie
    root.isEnd = false;
    // Safe to delete this node if it has no remaining children
    return root.children.size === 0;
  }

  const ch    = word[depth];
  const child = root.children.get(ch);
  if (!child) return false;  // word not in trie

  const shouldDelete = deleteWord(child, word, depth + 1);
  if (shouldDelete) {
    root.children.delete(ch);
    // This node can also be deleted if it is now a leaf non-word
    return !root.isEnd && root.children.size === 0;
  }
  return false;
}

// Longest common prefix of all words in trie
// Classic interview problem: walk single-child non-end chain
function longestCommonPrefix(trie) {
  let node   = trie.root;
  let prefix = '';
  // Continue while exactly one child and not end-of-word
  while (node.children.size === 1 && !node.isEnd) {
    const [ch, child] = node.children.entries().next().value;
    prefix += ch;
    node    = child;
  }
  return prefix;
}

// Count all words stored in trie — DFS node count
function countWords(node) {
  let count = node.isEnd ? 1 : 0;
  for (const child of node.children.values()) {
    count += countWords(child);
  }
  return count;
}

const t = new Trie();
['flower','flow','flight'].forEach(w => t.insert(w));
console.log(longestCommonPrefix(t));  // 'fl'
console.log(countWords(t.root));       // 3

deleteWord(t.root, 'flow', 0);
console.log(t.search('flow'));         // false
console.log(t.search('flower'));       // true — flower unaffected

