// 1. Word frequency trie — for ranked autocomplete
class FreqTrieNode {
  constructor() {
    this.children = new Map();
    this.isEnd    = false;
    this.freq     = 0;    // how often this word was inserted/searched
  }
}

class FreqTrie {
  constructor() { this.root = new FreqTrieNode(); }

  record(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) node.children.set(ch, new FreqTrieNode());
      node = node.children.get(ch);
    }
    node.isEnd = true;
    node.freq++;
  }

  // Top-3 suggestions for a prefix, sorted by frequency
  suggest(prefix, topK = 3) {
    let node = this.root;
    for (const ch of prefix) {
      if (!node.children.has(ch)) return [];
      node = node.children.get(ch);
    }
    const results = [];
    this.#collect(node, prefix, results);
    return results.sort((a, b) => b.freq - a.freq).slice(0, topK).map(r => r.word);
  }

  #collect(node, current, results) {
    if (node.isEnd) results.push({ word: current, freq: node.freq });
    for (const [ch, child] of node.children) {
      this.#collect(child, current + ch, results);
    }
  }
}

const ft = new FreqTrie();
const queries = ['apple','app','apple','application','app','app','apply'];
queries.forEach(q => ft.record(q));
console.log(ft.suggest('app'));
// ['app' (freq 3), 'apple' (freq 2), 'application' (freq 1)]

// 2. Longest word in dictionary that is a prefix of a given string
function longestPrefixMatch(trie, str) {
  let node   = trie.root;
  let last   = '';    // deepest isEnd seen so far
  let prefix = '';
  for (const ch of str) {
    if (!node.children.has(ch)) break;
    prefix += ch;
    node = node.children.get(ch);
    if (node.isEnd) last = prefix;
  }
  return last;
}

const dict = new Trie();
['a','ap','app','appl'].forEach(w => dict.insert(w));
console.log(longestPrefixMatch(dict, 'application')); // 'appl'
